import{_ as i,l as n,o as l,c as s,v as p,p as E,x as r,d as t,i as d,S as h,b as e}from"./chunks/framework.InCnrqk-.js";const N=JSON.parse('{"title":"专家粒度与数量律","description":"","frontmatter":{"title":"专家粒度与数量律","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/expert-granularity-law.md","filePath":"llm/expert-granularity-law.md","lastUpdated":1789023840000}'),B={name:"llm/expert-granularity-law.md"};function m(c,a,A,u,F,k){const o=n("Mermaid");return l(),s("div",null,[a[1]||(a[1]=p('<h1 id="专家粒度与数量律" tabindex="-1">专家粒度与数量律 <a class="header-anchor" href="#专家粒度与数量律" aria-label="Permalink to &quot;专家粒度与数量律&quot;">​</a></h1><div class="epigraph"><p>同样的激活预算，把一个宽 FFN 切成许多窄专家，有时比加几个宽专家更划算；系统账上窄专家却先把通信-计算比打穿。</p><footer>—— Krajewski et al., Scaling Laws for Fine-Grained Mixture of Experts, ICML 2024；Dai et al., DeepSeekMoE, 2024</footer></div><p>「架构进阶」最后一课把 MoE 单元收成一条可执行的律。<a href="/llm/moe-comm-compute-ratio">通信-计算比</a> 要求专家别太窄；DeepSeekMoE 与细粒度缩放律声称更细更好；<a href="/llm/peer-million-experts">PEER</a> 是细的极限。<a href="/llm/attention-moe">注意力 MoE</a> 不在这条律的适用域。本课写 FFN 专家的宽度–数量权衡，并标明何时停止切细。Clark 等人把路由模型的有效参数与激活计算分开拟合，提醒不能拿稠密 Chinchilla 系数直接套。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>固定每次前向的激活参数（\\(k\\) 个专家的宽度和），可以「少而宽」或「多而窄」。稠密缩放律不管这条轴。缺口是 MoE 自己的缩放：在激活 FLOPs 与数据量固定时，\\(N\\) 增大、\\(w\\) 减小，损失如何走，以及系统约束在哪一点把统计规律截断。</p><p>不要把「更多专家」写成「更大模型」。总参数可以涨而激活不变，那是稀疏；细粒度是在激活不变时改切法。两者在论文表里经常混报。共享专家是隐藏参数：常开宽枝把一部分 FLOPs 从 All-to-All 里拿出来，细路由枝才敢窄。</p><p><span class="marginnote">激活 FLOPs 不是总参数。律比较的是这条激活预算下的损失，不是「参数越多越好」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验轴：固定 \\(k\\cdot w\\cdot d\\)（含共享），扫 \\(N\\)（因而 \\(w\\propto 1/N\\) 若总中间宽均分），画验证损失。再固定 \\(N\\) 扫 \\(k\\)。第三条轴共享专家宽度。质量最优往往在较大 \\(N\\)、较小 \\(w\\)、\\(k\\gt 1\\)、加少量共享。然后叠加 \\(\\rho\\)、探针 Jaccard、召回类任务。</p><p>取部署点：在损失曲线仍下降、\\(\\rho\\) 可重叠、抖动可控的最大 \\(N\\)。不是损失最低的实验室点。节点受限与层次在大 \\(N\\) 上几乎是必选项。注意力专家宽度另算：上一课已说明 KV 与 \\(n\\) 会先撞墙。</p><p>哈希能支撑大 \\(N\\) 但不给内容特化，损失平台更高。Soft 不能把 \\(N\\) 做大。预训练用细粒度，部署再按<a href="/llm/expert-pruning-merging">剪枝合并</a> 收回 \\(N\\)，是一条兼容路径。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>更细的专家让门做更细的 Voronoi，组合数 \\(\\binom{N}{k}\\) 增大，同样激活下表达力上升——前提是门学得会、token 真的需要不同切片。过细时单个专家看不见连续短语，且 \\(\\rho\\) 变差、边界 token 更易抖。共享专家提供不必切片的公共基底，允许叶子更窄。</p><p>因此粒度不是单调的「越细越好」。有共享、节点受限、\\(k\\) 足够时，细切窗口变宽；平坦 Switch、\\(k=1\\)、无共享时，窗口很窄。数据不够时大 \\(N\\) 的叶子吃不饱，律逆转：宁宽勿细。报律必须声明这些配方。</p><p><span class="marginnote">这条律不迁移到注意力专家，也不迁移到 SSM 状态维。专家是 FFN 容量，不是 KV，不是序列记忆。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在小规模代理上扫完细粒度就直接乘到万亿。不要把 PEER 的百万当成目标点。微调后最优会漂移；预训练的粒度要给剪枝留冗余簇。课序到此结束「架构进阶」。下一课转入预训练工程的分词器：<a href="/llm/pretokenization-regex">预分词正则</a> 问序列怎么切，不再问专家怎么切。设计检查清单：激活预算、\\(N\\) 与 \\(w\\)、共享、\\(k\\)、\\(M\\)、\\(\\rho\\)、抖动指标、是否只 FFN 专家。</p>',17)),(l(),E(h,null,{default:r(()=>[d(o,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20Act%5B%22%E5%9B%BA%E5%AE%9A%E6%BF%80%E6%B4%BB%20FLOPs%22%5D%20--%3E%20Fine%5B%22%E6%9B%B4%E5%A4%A7%20N%20%E6%9B%B4%E7%AA%84%20w%22%5D%0A%20%20Fine%20--%3E%20Loss%5B%22%E6%8D%9F%E5%A4%B1%E4%B8%8B%E9%99%8D%22%5D%0A%20%20Fine%20--%3E%20Rho%5B%22%E9%80%9A%E4%BF%A1%E6%AF%94%E6%81%B6%E5%8C%96%22%5D%0A%20%20Fine%20--%3E%20Flip%5B%22%E6%8A%96%E5%8A%A8%E5%A2%9E%E5%8A%A0%22%5D%0A%20%20Shared%5B%22%E5%85%B1%E4%BA%AB%E4%B8%93%E5%AE%B6%22%5D%20--%3E%20Fine%0A%20%20Loss%20--%3E%20Pick%5B%22%E9%83%A8%E7%BD%B2%E7%82%B9%EF%BC%9A%E6%8D%9F%E5%A4%B1%E4%B8%8E%E7%B3%BB%E7%BB%9F%E4%BA%A4%E6%B1%87%22%5D%0A%20%20Rho%20--%3E%20Pick%0A%20%20Flip%20--%3E%20Pick%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[t("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"同样激活 FLOPs 下，FFN 专家偏多而窄往往更参数高效，直到通信、抖动与叶子吃不饱截断。"),e("li",null,"共享专家是细粒度的配套；部署点不等于实验室最低损失。"),e("li",null,"律只覆盖 FFN 专家，不含注意力 MoE 与 SSM 状态。"),e("li",null,"剪枝可以训细推粗。"),e("li",null,"出处：Krajewski et al., ICML 2024；Dai et al., 2024；Clark et al. 对路由缩放的讨论。")],-1))])}const x=i(B,[["render",m]]);export{N as __pageData,x as default};
